for(const [group,items]of Object.entries(fields)){const root=$(group==='basic'?'basicFields':group==='follow'?'followFields':group==='risk'?'riskFields':'gasFields');const grid=document.createElement('div');grid.className='row';for(const [id,label,value]of items){const div=document.createElement('div'),l=document.createElement('label'),input=document.createElement('input');l.htmlFor=id;l.textContent=label;input.id=id;input.inputMode='decimal';input.placeholder='\u81EA\u884C\u586B\u5199';if(value!=null)input.value=value;div.append(l,input);grid.append(div);}root.append(grid);}
