function units(v,d=18,n=6){if(v==null)return '\u2014';let x=BigInt(v),neg=x<0n;if(neg)x=-x;const u=10n**BigInt(d),i=x/u,f=(x%u).toString().padStart(d,'0').slice(0,n).replace(/0+$/,'');return (neg?'-':'')+i.toLocaleString()+(f?'.'+f:'');}
