 $('lastSeen').textContent=s?.updatedAt?'\u76D8\u53E3 '+cn(s.updatedAt).slice(11):'\u5C1A\u672A\u540C\u6B65';const age=s?.heartbeat?Math.floor((Date.now()-s.heartbeat)/1000):null;$('heartbeat').textContent=age==null?'\u672A\u542F\u52A8\u4E91\u7AEF\u5468\u671F':age>120?'\u4E91\u7AEF\u6700\u8FD1\u5FC3\u8DF3\u5DF2\u8FC7\u53BB '+age+' \u79D2\uFF0C\u8BF7\u6838\u5BF9\u8FDE\u63A5\u548C\u65E5\u5FD7':'\u4E91\u7AEF\u5FC3\u8DF3 '+age+' \u79D2\u524D';$('health').classList.toggle('stale',age!=null&&age>120);if(s?.activeSession&&s?.quoteExpiry)$('heartbeat').textContent+=' \xB7 \u672C\u6B21\u8FD0\u884C\u81F3 '+cn(s.quoteExpiry)+'\uFF08\u5317\u4EAC\u65F6\u95F4\uFF09';
